#include "resident/domains/interaction/visit_appointments/visit_appointment_world.hpp"
// 未启用新段绝不从普通会话补预约；同候选完整冷验后只返回原事实或原Action，不重放开始。
#include "personal_appointment_world.hpp"
#include "personal_appointment_presence.hpp"
#include "personal_appointment_native.hpp"
#include "resident/kernel/world_bundle.hpp"
namespace hanmo::resident {namespace {
Outcome<const PersonalAppointmentTime2Context*> original_context(const WorldBundle&w,const PersonalAppointmentTime2Context*supplied,std::shared_ptr<const PersonalAppointmentExactReadLease>&owner){if(!w.interaction.personal_appointments||w.interaction.personal_appointments->version==1){if(supplied)return {false,{},common_failure("PersonalAppointmentVersionMismatch",{},ErrorKind::internal).error};return {true,nullptr,{}};}if(supplied){if(&supplied->common!=&w.common||&supplied->state!=&*w.interaction.personal_appointments)return {false,{},common_failure("PersonalAppointmentCandidateMismatch",{},ErrorKind::internal).error};return {true,supplied,{}};}auto now=w.actual_phase_moment();if(!now.ok)return {false,{},now.error};auto factory=native_personal_appointment_exact_world_factory();auto result=factory.read(w,now.value);if(!result.ok)return {false,{},result.error};owner=std::move(result.value);return owner->context();}
Status enabled(const WorldBundle& w){return w.dynamic_enabled()&&w.catalog->personal_appointments&&w.interaction.personal_appointments?common_success():common_failure("PersonalAppointmentProfileRequired");}
}
Outcome<std::vector<StableId>> personal_appointment_new_result_world(const WorldBundle& before,const WorldBundle& after,const StableId& actor,const StableId& kind,const ReceiptDetails& details){return personal_appointment_new_result_sources(before.interaction.personal_appointments?&*before.interaction.personal_appointments:nullptr,after.interaction.personal_appointments?&*after.interaction.personal_appointments:nullptr,actor,kind,details,after.common.tick());}
Status bind_personal_appointment_result_world(WorldBundle& world,const std::vector<StableId>& sources,const StableId& actor,Integer sequence,const CommitResult& result,const PersonalAppointmentTime2Context*exact){std::shared_ptr<const PersonalAppointmentExactReadLease> owning;auto actual=original_context(world,exact,owning);if(!actual.ok)return {false,{},actual.error};exact=actual.value;if(!world.interaction.personal_appointments)return sources.empty()?common_success():common_failure("PersonalAppointmentProfileRequired");auto v=bind_personal_appointment_player_result(world.common,*world.interaction.personal_appointments,sources,actor,sequence,result);if(!v.ok)return v;if(world.interaction.personal_appointments->version==2){if(!exact)return common_failure("PersonalAppointmentTime2ContextRequired",{},ErrorKind::unsupported_capability);return bind_personal_appointment_time2_command_result(world.common,*world.interaction.personal_appointments,*exact,sources,result);}return common_success();}
Status validate_personal_appointment_world(const WorldBundle& w,const PersonalAppointmentTime2Context*exact){std::shared_ptr<const PersonalAppointmentExactReadLease> owning;auto actual=original_context(w,exact,owning);if(!actual.ok)return {false,{},actual.error};exact=actual.value;
    const auto* state=w.interaction.personal_appointments?&*w.interaction.personal_appointments:nullptr;auto valid=validate_personal_appointment_layout(w.common,w.catalog->identity.module_versions,w.catalog->personal_appointments.get(),state);if(!valid.ok)return valid;
    if(w.catalog->personal_appointments){valid=enabled(w);if(!valid.ok)return valid;valid=validate_personal_appointments(w.common,w.interaction,*w.catalog->interaction,*w.catalog->personal_appointments,*state,nullptr,exact);if(!valid.ok)return valid;if(state->version==1)valid=validate_personal_appointment_presence(w.common,*w.catalog->common,*state,w.family_death_read());if(!valid.ok)return valid;}
    return validate_personal_appointment_cached_results(w.common,state);
}
Outcome<PersonalAppointmentQuote> prepare_personal_appointment_world(const WorldBundle& w,const StableId& actor,const PersonalAppointmentCommand& command,const PersonalAppointmentTime2Context*exact){std::shared_ptr<const PersonalAppointmentExactReadLease> owning;auto actual=original_context(w,exact,owning);if(!actual.ok)return {false,{},actual.error};exact=actual.value;
    auto valid=enabled(w);if(!valid.ok)return {false,{},valid.error};auto access=w.services.interaction_access();return std::visit([&](const auto& c)->Outcome<PersonalAppointmentQuote>{using T=std::decay_t<decltype(c)>;
        if constexpr(std::is_same_v<T,PersonalAppointmentAccept>){auto quote=preview_personal_appointment_accept(w.common,w.interaction,*w.catalog->interaction,access,*w.catalog->personal_appointments,*w.interaction.personal_appointments,actor,c,exact);if(!quote.ok)return quote;auto conflict=check_visit_appointment_personal_accept_world(w,quote.value);if(!conflict.ok)return {false,{},conflict.error};return quote;}
        else if constexpr(std::is_same_v<T,PersonalAppointmentCancel>)return preview_personal_appointment_cancel(w.common,w.interaction,*w.catalog->interaction,access,*w.catalog->personal_appointments,*w.interaction.personal_appointments,actor,c,exact);
        else return preview_personal_appointment_meet(w.common,w.interaction,*w.catalog->interaction,access,*w.catalog->personal_appointments,*w.interaction.personal_appointments,actor,c,exact);
    },command);
}
Outcome<PersonalAppointmentWorldResult> commit_personal_appointment_world(WorldBundle& w,const StableId& actor,const PersonalAppointmentCommand& command,const PersonalAppointmentQuote& quote,const PersonalAppointmentTime2Context*exact){std::shared_ptr<const PersonalAppointmentExactReadLease> owning;auto actual=original_context(w,exact,owning);if(!actual.ok)return {false,{},actual.error};exact=actual.value;
    auto valid=enabled(w);if(!valid.ok)return {false,{},valid.error};if(actor!=quote.consent.meeting.actor_id)return {false,{},common_failure("StalePersonalAppointmentQuote").error};auto access=w.services.interaction_access();
    return std::visit([&](const auto& c)->Outcome<PersonalAppointmentWorldResult>{using T=std::decay_t<decltype(c)>;Outcome<StableId> result;
        if constexpr(std::is_same_v<T,PersonalAppointmentAccept>){if(c.policy_id!=quote.policy_id||!quote.appointment_id.empty())return {false,{},common_failure("StalePersonalAppointmentQuote").error};auto conflict=check_visit_appointment_personal_accept_world(w,quote);if(!conflict.ok)return {false,{},conflict.error};result=accept_personal_appointment_in_candidate(w.common,w.interaction,*w.catalog->interaction,access,*w.catalog->personal_appointments,*w.interaction.personal_appointments,quote,exact);}
        else {if(c.appointment_id!=quote.appointment_id)return {false,{},common_failure("StalePersonalAppointmentQuote").error};if constexpr(std::is_same_v<T,PersonalAppointmentCancel>)result=cancel_personal_appointment_in_candidate(w.common,w.interaction,*w.catalog->interaction,access,*w.catalog->personal_appointments,*w.interaction.personal_appointments,quote,exact);else result=start_personal_appointment_in_candidate(w.common,w.interaction,*w.catalog->interaction,access,*w.catalog->personal_appointments,*w.interaction.personal_appointments,quote,exact,w.action_elapsed?&*w.action_elapsed:nullptr);}
        if(!result.ok)return {false,{},result.error};return {true,{std::is_same_v<T,PersonalAppointmentMeet>,result.value},{}};
    },command);
}
Outcome<PersonalAppointmentCompletion> step_personal_appointment_world(WorldBundle& w,const ActionCoreView& action,const DynamicStepInput& phase){auto valid=enabled(w);if(!valid.ok)return {false,{},valid.error};auto access=w.services.interaction_access();return finish_personal_appointment_in_candidate(w.common,w.interaction,*w.catalog->interaction,access,*w.catalog->personal_appointments,*w.interaction.personal_appointments,action,phase);}
Outcome<BoundaryValue> query_personal_appointment_world(const WorldBundle& w,Integer cursor,const PersonalAppointmentTime2Context*exact){std::shared_ptr<const PersonalAppointmentExactReadLease> owning;auto actual=original_context(w,exact,owning);if(!actual.ok)return {false,{},actual.error};exact=actual.value;auto valid=enabled(w);if(!valid.ok)return {false,{},valid.error};auto access=w.services.interaction_access();return query_personal_appointments(w.common,{*w.catalog->common,w.interaction,*w.catalog->interaction,access,*w.catalog->personal_appointments,*w.interaction.personal_appointments,exact},cursor);}
Outcome<std::optional<PersonalAppointmentActionSource>> query_personal_appointment_action_world(const WorldBundle&w,const StableId&actor,const StableId&action,const PersonalAppointmentTime2Context*exact){std::shared_ptr<const PersonalAppointmentExactReadLease>owning;auto actual=original_context(w,exact,owning);if(!actual.ok)return {false,{},actual.error};auto valid=enabled(w);if(!valid.ok)return {false,{},valid.error};return query_personal_appointment_action(w.common,*w.interaction.personal_appointments,actor,action,actual.value);}
Outcome<std::optional<PersonalAppointmentActionSource>> query_personal_appointment_completion_world(const WorldBundle&w,const StableId&actor,const StableId&action,const ReceiptDetails&details,Integer tick,const StableId&result,const PersonalAppointmentTime2Context*exact){std::shared_ptr<const PersonalAppointmentExactReadLease>owning;auto actual=original_context(w,exact,owning);if(!actual.ok)return {false,{},actual.error};auto valid=enabled(w);if(!valid.ok)return {false,{},valid.error};return query_personal_appointment_completion(w.common,*w.interaction.personal_appointments,actor,action,details,tick,result,actual.value);}

}
